import{_ as e,o as a,c as s,ao as i}from"./chunks/framework.BK8xRsUh.js";const c=JSON.parse('{"title":"Worked examples","description":"","frontmatter":{},"headers":[],"relativePath":"examples.md","filePath":"examples.md","lastUpdated":null}'),n={name:"examples.md"};function r(o,t,l,h,d,p){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="Worked-examples" tabindex="-1">Worked examples <a class="header-anchor" href="#Worked-examples" aria-label="Permalink to &quot;Worked examples {#Worked-examples}&quot;">​</a></h1><p>The <code>examples/</code> folder holds two complete synthetic surveys and a set of short scripts for the everyday jobs.</p><h2 id="A-note-on-the-data" tabindex="-1">A note on the data <a class="header-anchor" href="#A-note-on-the-data" aria-label="Permalink to &quot;A note on the data {#A-note-on-the-data}&quot;">​</a></h2><p>Both surveys are <strong>synthetic</strong>. Every model, station position and gravity value in them is computed, not measured. They are placed on the Finnish national grid (ETRS-TM35FIN, <code>EPSG:3067</code>) around the GTK office in Otaniemi, Espoo, so that coordinates, ground elevations, anomaly amplitudes and error bars read like a real ground survey in Finnish Precambrian bedrock. No measured data is distributed with this package.</p><h2 id="Run-them" tabindex="-1">Run them <a class="header-anchor" href="#Run-them" aria-label="Permalink to &quot;Run them {#Run-them}&quot;">​</a></h2><p>Each demo folder splits running from plotting. <code>00_run_inv_GN.jl</code> and <code>00_run_inv_INR.jl</code> invert the survey into a timestamped <code>run_gn_&lt;timestamp&gt;/</code> or <code>run_inr_&lt;timestamp&gt;/</code>; nothing is plotted automatically:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/demo1/00_run_inv_GN.jl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/demo1/00_run_inv_INR.jl</span></span></code></pre></div><p>Then plot whatever runs you have, on demand:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/demo1/01_plot_data.jl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/demo1/02_plot_model_XY.jl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/demo1/03_plot_model_XZ.jl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/demo1/04_plot_model_YZ.jl</span></span></code></pre></div><p>Each plotting script finds the latest GN and INR run next to it and compares them against <code>model.true</code>; run only one algorithm and it plots just that one. The run and plot folders are gitignored, so you always reproduce them locally rather than reading someone else&#39;s output.</p><h2 id="demo1-—-blocky-targets,-dense-grid" tabindex="-1"><code>demo1</code> — blocky targets, dense grid <a class="header-anchor" href="#demo1-—-blocky-targets,-dense-grid" aria-label="Permalink to &quot;\`demo1\` — blocky targets, dense grid {#demo1-—-blocky-targets,-dense-grid}&quot;">​</a></h2><p>289 stations on a 100 m grid over 1.6 × 1.6 km of gently rolling coastal bedrock (ground 4–38 m). Two uniform ±200 kg/m³ blocks sit at 100–400 m depth: a mafic intrusion in granitic gneiss, and a clay-filled bedrock depression. The anomaly runs −0.75 to +0.73 mGal with 2 % + 5 µGal errors.</p><p>This is the classical setting, and Gauss–Newton takes it: correlation 0.66 against the INR&#39;s 0.63, reaching RMS 0.99 in a single step where the INR needs 281 epochs.</p><p>Both overshoot the mass and put it too deep — 15.8 Mt at 447 m and 12.6 Mt at 403 m against a true 8.8 Mt at 245 m. That is ordinary gravity depth ambiguity, not a failure of either method, and it is worth seeing on a case where you know the answer.</p><h2 id="demo2-—-gradational-target,-sparse-survey" tabindex="-1"><code>demo2</code> — gradational target, sparse survey <a class="header-anchor" href="#demo2-—-gradational-target,-sparse-survey" aria-label="Permalink to &quot;\`demo2\` — gradational target, sparse survey {#demo2-—-gradational-target,-sparse-survey}&quot;">​</a></h2><p>A basin 280 m deep whose fill grades from −200 kg/m³ at the surface to background at the floor, beside a 200 × 200 × 193 m block of +260 kg/m³ — a glacially scoured bedrock depression filled with soft sediment next to a mafic body, about 2 km north-west of the <code>demo1</code> site. 150 scattered stations, with no access inside a 130 m clearing between the two bodies: 12 600 cells to constrain with 150 data.</p><p>Two things here are chosen to suit a coordinate network, and both are ordinary field conditions rather than tricks: the truth is a <strong>continuous function of position</strong> rather than a set of uniform blocks, and the survey is <strong>sparse and irregular</strong>.</p><p>Scored over the core against a true −3.05 Mt deficit at 52 m and +2.01 Mt excess at 147 m:</p><table tabindex="0"><thead><tr><th style="text-align:right;"></th><th style="text-align:right;">RMS</th><th style="text-align:right;">iterations</th><th style="text-align:right;">correlation</th><th style="text-align:right;">deficit</th><th style="text-align:right;">its centroid</th><th style="text-align:right;">excess</th><th style="text-align:right;">its centroid</th></tr></thead><tbody><tr><td style="text-align:right;">Gauss–Newton</td><td style="text-align:right;">0.95</td><td style="text-align:right;">3</td><td style="text-align:right;">0.61</td><td style="text-align:right;">−6.34 Mt</td><td style="text-align:right;">189 m</td><td style="text-align:right;">+2.52 Mt</td><td style="text-align:right;">188 m</td></tr><tr><td style="text-align:right;">INR</td><td style="text-align:right;">0.99</td><td style="text-align:right;">257</td><td style="text-align:right;"><strong>0.81</strong></td><td style="text-align:right;"><strong>−2.89 Mt</strong></td><td style="text-align:right;"><strong>54 m</strong></td><td style="text-align:right;">+1.52 Mt</td><td style="text-align:right;"><strong>119 m</strong></td></tr></tbody></table><p>Gauss–Newton buys the misfit with twice the mass it needs, buried below 180 m, and speckles the top layer where stations are sparse. The network returns a coherent bowl that shrinks with depth like the true one, and a compact block in place.</p><p>Gauss–Newton is not strawmanned: across stronger smallness, heavier smoothing, depth weighting and no weighting, its correlation stays between 0.41 and 0.65 and the basin centroid never comes shallower than 149 m.</p><p>The data are forward-modelled on a 2× refinement of the inversion mesh and given 2 % + 3 µGal noise, so the forward model sees structure no 40 m cell can hold — the true model <em>on the inversion mesh</em> only fits the data at RMS 2.14. That is deliberate: a synthetic where the truth fits perfectly is easier than any real survey.</p><h2 id="The-short-scripts" tabindex="-1">The short scripts <a class="header-anchor" href="#The-short-scripts" aria-label="Permalink to &quot;The short scripts {#The-short-scripts}&quot;">​</a></h2><p>Each has a settings block at the top to edit, and sensible defaults so it runs as-is.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Script</th><th style="text-align:right;">What it does</th></tr></thead><tbody><tr><td style="text-align:right;"><code>make_mesh3D.jl</code></td><td style="text-align:right;">design a mesh, start model and covariance around a survey</td></tr><tr><td style="text-align:right;"><code>run_fwd3D.jl</code></td><td style="text-align:right;">predict gravity from a model at a survey&#39;s stations</td></tr><tr><td style="text-align:right;"><code>run_inv3D.jl</code></td><td style="text-align:right;">run an inversion and plot it; the control file picks the algorithm</td></tr><tr><td style="text-align:right;"><code>plot_data3D.jl</code></td><td style="text-align:right;">map a survey, or observed/predicted/residual together</td></tr><tr><td style="text-align:right;"><code>plot_model3D.jl</code></td><td style="text-align:right;">open a model in a slice, section or 3D viewer</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/make_mesh3D.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/demo1/data.xyz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/run_inv3D.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/demo1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> InvCtrl.INR</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/plot_model3D.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/demo1/model.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xz</span></span></code></pre></div><h2 id="What-ships,-and-what-you-make" tabindex="-1">What ships, and what you make <a class="header-anchor" href="#What-ships,-and-what-you-make" aria-label="Permalink to &quot;What ships, and what you make {#What-ships,-and-what-you-make}&quot;">​</a></h2><p>Each demo folder holds <strong>inputs only</strong> — the files a six-file <code>Invert3D</code> call needs, plus <code>model.true</code> so you can score the result yourself. Everything a run produces (run folders, outputs, figures) is gitignored and regenerated when you run it.</p>`,28)])])}const k=e(n,[["render",r]]);export{c as __pageData,k as default};
